238:   if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
239:   const ops = [];
240:   const n = patch.length;
241:   for (let i = 0; i < n; i++) {
242:     const checked = checkOp(patch[i]);
243:     if (typeof checked === 'string') throw new PatchError(`operation ${i}: ${checked}`, i);
