 79: function depthOf(value) {
 80:   let max = 0;
 81:   const stack = [[value, 0]];
 82:   while (stack.length > 0) {
 83:     const [v, d] = stack.pop();
 84:     if (typeof v !== 'object' || v === null) continue;
 85:     const depth = d + 1;
 86:     if (depth > max) max = depth;
 87:     if (max > MAX_DEPTH) return max;
 88:     for (const child of Array.isArray(v) ? v : Object.values(v)) {
 89:       if (typeof child === 'object' && child !== null) stack.push([child, depth]);
 90:     }
 91:   }
 92:   return max;
 93: }
