104:   }
105:   let value;
106:   try {
107:     value = JSON.parse(text);
108:   } catch {
109:     throw new CliError(`Error: ${name}: invalid JSON`, 3);
110:   }
111:   if (depthOf(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
112:   return value;
113: }
